// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<p data-line=\"0\" class=\"code-line\">This article summarizes how Angular Resources will change in the next release, based on GitHub discussion threads and related commits.</p>\n<ul data-line=\"2\" class=\"code-line\">\n<li data-line=\"2\" class=\"code-line\">\n<p data-line=\"2\" class=\"code-line\"><a href=\"https://github.com/angular/angular/discussions/60121\" target=\"_blank\" rel=\"noopener noreferrer\">[Complete] Resource RFC 2: APIs #60121</a></p>\n</li>\n<li data-line=\"4\" class=\"code-line\">\n<p data-line=\"4\" class=\"code-line\"><a href=\"https://github.com/angular/angular/commit/b35396345cb48f9ce1e318d2c7f056eb6a7c9bb4\" target=\"_blank\" rel=\"noopener noreferrer\">b35396345cb48f9ce1e318d2c7f056eb6a7c9bb4</a></p>\n</li>\n<li data-line=\"5\" class=\"code-line\">\n<p data-line=\"5\" class=\"code-line\"><a href=\"https://github.com/angular/angular/commit/905194fa57b048364b4c3a2333083888a43f77ca\" target=\"_blank\" rel=\"noopener noreferrer\">905194fa57b048364b4c3a2333083888a43f77ca</a></p>\n</li>\n<li data-line=\"6\" class=\"code-line\">\n<p data-line=\"6\" class=\"code-line\"><a href=\"https://github.com/angular/angular/commit/05eb028c7ae670e60f651cdbecb14ee0d73552e9\" target=\"_blank\" rel=\"noopener noreferrer\">05eb028c7ae670e60f651cdbecb14ee0d73552e9</a></p>\n</li>\n<li data-line=\"7\" class=\"code-line\">\n<p data-line=\"7\" class=\"code-line\"><a href=\"https://github.com/angular/angular/commit/07811ddd7d4f027e60cb33ecf341e8d1d5675a8a\" target=\"_blank\" rel=\"noopener noreferrer\">07811ddd7d4f027e60cb33ecf341e8d1d5675a8a</a></p>\n</li>\n<li data-line=\"8\" class=\"code-line\">\n<p data-line=\"8\" class=\"code-line\"><a href=\"https://github.com/angular/angular/commit/d0c9a6401a388ae5cd2ca40439b48781ceff95ef\" target=\"_blank\" rel=\"noopener noreferrer\">d0c9a6401a388ae5cd2ca40439b48781ceff95ef</a></p>\n</li>\n</ul>\n<p data-line=\"10\" class=\"code-line\">Resources remain experimental and are expected to stay experimental through v20—more changes may follow.</p>\n<h2 id=\"1.-improved-error-handling\" data-line=\"13\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#1.-improved-error-handling\" aria-hidden=\"true\"></a> 1. Improved error handling</h2>\n<h2 id=\"change-in-resource.value()-behavior\" data-line=\"15\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#change-in-resource.value()-behavior\" aria-hidden=\"true\"></a> Change in Resource.value() behavior</h2>\n<p data-line=\"17\" class=\"code-line\">Previously, when a resource was in an error state, <code>resource.value()</code> returned <code>undefined</code>. In the new implementation, reading <code>resource.value()</code> while in an error state throws an exception.<br>\nYou must handle errors explicitly.</p>\n<p data-line=\"20\" class=\"code-line\"><strong>Previous behavior</strong>: errors were hidden by default</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"21\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> res</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  loader</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Before (errors are hidden)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> inner</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> computed</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> res.</span><span style=\"color:#B392F0\">value</span><span style=\"color:#E1E4E8\">()?.inner);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"30\" class=\"code-line\"><strong>New behavior</strong>: explicit error handling required</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"31\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> res</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  loader</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Option 1: Return defaultValue (initially undefined) instead of Errors</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  throwErrorsFromValue: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Option 2: Handle the error</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> inner</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> computed</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (res.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">()) </span><span style=\"color:#F97583\">return</span><span style=\"color:#79B8FF\"> undefined</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> res.</span><span style=\"color:#B392F0\">value</span><span style=\"color:#E1E4E8\">()?.inner;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"error-handling-in-templates\" data-line=\"47\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#error-handling-in-templates\" aria-hidden=\"true\"></a> Error handling in templates</h2>\n<p data-line=\"49\" class=\"code-line\">The same applies in HTML templates. If you used <code>resource.value()</code> as optional, check errors—not just <code>isLoading</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"51\"><span class=\"line\"><span style=\"color:#E1E4E8\">@if (res.isLoading()) {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  &lt;!-- Content while loading --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">} @else if (res.error()) {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  &lt;!-- Content on error --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">} @else {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  &lt;!-- Content on success --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"61\" class=\"code-line\">Details:</p>\n<ul data-line=\"63\" class=\"code-line\">\n<li data-line=\"63\" class=\"code-line\">Reloading while in an error state sets <code>hasValue()</code> to <code>true</code> and <code>value()</code> returns <code>defaultValue</code></li>\n<li data-line=\"64\" class=\"code-line\">When a new value loads successfully, <code>error()</code> becomes <code>undefined</code></li>\n</ul>\n<h2 id=\"clearer-resource.error-typing\" data-line=\"66\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#clearer-resource.error-typing\" aria-hidden=\"true\"></a> Clearer Resource.error typing</h2>\n<p data-line=\"68\" class=\"code-line\"><code>Resource.error</code> changes from <code>unknown</code> to <code>Error | undefined</code>, enabling type-safe error handling.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"70\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> error</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> resource.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">if</span><span style=\"color:#E1E4E8\"> (error </span><span style=\"color:#F97583\">instanceof</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Type-safe access to error.message and other properties</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"77\" class=\"code-line\">Type guards make error handling easier. Also, values thrown that are not <code>Error</code> instances are wrapped in <code>ResourceWrappedError</code> for consistent handling.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"79\"><span class=\"line\"><span style=\"color:#F97583\">if</span><span style=\"color:#E1E4E8\"> (resource.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">instanceof</span><span style=\"color:#B392F0\"> ResourceWrappedError</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> original</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> resource.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">().cause;</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // original can be an API error object, for example</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"86\" class=\"code-line\"><a href=\"https://github.com/angular/angular/blob/d3e9ca1162a0d72e78708fcce5644b9b25e4d487/packages/core/src/resource/resource.ts#L469-L478\" rel=\"noopener noreferrer\" target=\"_blank\">https://github.com/angular/angular/blob/d3e9ca1162a0d72e78708fcce5644b9b25e4d487/packages/core/src/resource/resource.ts#L469-L478</a><a href=\"https://github.com/angular/angular/blob/d3e9ca1162a0d72e78708fcce5644b9b25e4d487/packages/core/src/resource/resource.ts#L469-L478\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/angular/angular/blob/d3e9ca1162a0d72e78708fcce5644b9b25e4d487/packages/core/src/resource/resource.ts#L469-L478</a></p>\n<h2 id=\"2.-reload()-moved\" data-line=\"88\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#2.-reload()-moved\" aria-hidden=\"true\"></a> 2. reload() moved</h2>\n<p data-line=\"90\" class=\"code-line\"><code>reload()</code> is available only on <code>WritableResource</code>, separating \"reloadable resources\" from read-only resources.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"92\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> res</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Data</span><span style=\"color:#E1E4E8\">&gt;({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  loader</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">), </span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// It is a WritableResource, so the `reload` method is available</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">res.</span><span style=\"color:#B392F0\">reload</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// It is not Writable, so the `reload` method is unavailable</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">res.</span><span style=\"color:#B392F0\">asReadonly</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">res.</span><span style=\"color:#B392F0\">reload</span><span style=\"color:#E1E4E8\">(); </span><span style=\"color:#a0aab5\">// NG</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"3.-parameter-rename\" data-line=\"105\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#3.-parameter-rename\" aria-hidden=\"true\"></a> 3. Parameter rename</h2>\n<p data-line=\"107\" class=\"code-line\"><code>request</code> becomes <code>params</code> for clearer intent.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"109\"><span class=\"line\"><span style=\"color:#a0aab5\">// Before</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> res</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">&gt;({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  request</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> ({id: </span><span style=\"color:#B392F0\">userId</span><span style=\"color:#E1E4E8\">()}),</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  loader</span><span style=\"color:#E1E4E8\">: ({</span><span style=\"color:#FFAB70\">request</span><span style=\"color:#E1E4E8\">}) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#9ECBFF\">`/api/users/${</span><span style=\"color:#E1E4E8\">request</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">id</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// After</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> res</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">&gt;({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  params</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> ({id: </span><span style=\"color:#B392F0\">userId</span><span style=\"color:#E1E4E8\">()}),</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  loader</span><span style=\"color:#E1E4E8\">: ({</span><span style=\"color:#FFAB70\">params</span><span style=\"color:#E1E4E8\">}) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#9ECBFF\">`/api/users/${</span><span style=\"color:#E1E4E8\">params</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">id</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"127\" class=\"code-line\"><code>httpResource</code> also takes a function instead of a static URL.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"129\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> userId</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> res</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> httpResource</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">&gt;(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#9ECBFF\"> `/api/users/${</span><span style=\"color:#B392F0\">userId</span><span style=\"color:#9ECBFF\">()</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"summary\" data-line=\"134\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"136\" class=\"code-line\">There is more—for example, <code>map</code> in <code>httpResource</code> was renamed to <code>parse</code>—but I hope this helps you anticipate changes before release.</p>\n<blockquote data-line=\"138\" class=\"code-line\">\n<p data-line=\"138\" class=\"code-line\">The Resource story in Angular is just starting and will be evolving. To reflect this, the resource APIs will remain experimental in Angular v20. We will persuade the stabilization process and embark on designing additional APIs and functionality in the subsequent releases. Your continued feedback is crucial: play with Angular v20, build on top of it and open GitHub issues for any problems or enhancements that should be considered.<a href=\"https://github.com/angular/angular/discussions/60121#discussioncomment-12654043\" target=\"_blank\" rel=\"noopener noreferrer\">from discussioncomment-12654043</a></p>\n</blockquote>\n<p data-line=\"140\" class=\"code-line\">I look forward to Resources becoming safer and easier to use.</p>\n<p data-line=\"142\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"1.-improved-error-handling","text":"1. Improved error handling","level":2},{"id":"change-in-resource.value()-behavior","text":"Change in Resource.value() behavior","level":2},{"id":"error-handling-in-templates","text":"Error handling in templates","level":2},{"id":"clearer-resource.error-typing","text":"Clearer Resource.error typing","level":2},{"id":"2.-reload()-moved","text":"2. reload() moved","level":2},{"id":"3.-parameter-rename","text":"3. Parameter rename","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
